        number: "21",
        id: "gbv-section-7-21",
        title: "Glossary",
        blocks: [
          {
            type: "paragraph",
            text: "Emotional abuse: Behavior that undermines emotional wellbeing through degradation, threats, manipulation or other harmful treatment. Psychological abuse: Abusive behavior that creates fear, distress or coercion, including nonverbal control.",
          },
          {
            type: "paragraph",
            text: "Verbal abuse: Insults, degrading language, threats or humiliating speech used to harm or control.",
          },
          {
            type: "paragraph",
            text: "Coercive control: A pattern of behaviors that limits choices and independence.",
          },
          {
            type: "paragraph",
            text: "Intimidation: Actions or communication used to create fear.",
          },
          {
            type: "paragraph",
            text: "Survivor-centred: An approach prioritizing safety, dignity, informed choices and individual needs.",
          },
          {
            type: "paragraph",
            text: "Safeguarding: Procedures to protect people, especially children and at-risk people, from harm.",
          },
          {
            type: "paragraph",
            text: "Referral: Connecting a person to an appropriate qualified service according to need and safety.",
          },
        ],
